#!/bin/bash
# run_little_prof.sh — Operational pipeline for Little Professor, on survey arrival.
# Generated by install.py from slopes/little_prof/slope_config.toml
#
# Runs after a new UAS survey lands:
#   resample → transport → avalanche → gap_fill → cluster_update → smet
#   → smet_append → nwp_ingest → SNOWPACK survey cycle → analyze → scenarios
#
# The SNOWPACK survey cycle (src/avachain/snowpack_cycle.py) re-runs from the
# PREVIOUS survey's state, because the window since then is now bracketed by
# two surveys and gap_fill has rebuilt its forcing from both. Avalanches that
# `avalanche` detected in that window split the run: stop at the event,
# analyze, scour the release clusters' .sno, continue. The new survey's state
# is saved as the next survey anchor, the state at T_stable as the daily
# anchor, and the main Zarr is replaced after the previous survey.
#
# Usage:
#   ./run_little_prof.sh                          # latest visible survey
#   ./run_little_prof.sh --snapshot 2026-03-14
#   ./run_little_prof.sh --n-triggers 3
#   ./run_little_prof.sh --no-nwp                 # skip NWP forecast extension
#   ./run_little_prof.sh --no-cluster-update      # keep cluster ids frozen
#   ./run_little_prof.sh --no-scenarios           # stop after analyze
#
# Hand-labelled avalanches enter through the known-events file read by the
# `avalanche` step, not through flags here.
#
# Prerequisites:
#   - Full pipeline run at least once (cluster map exists)
#   - Survey and daily anchors exist (snowpack_cycle.py init-anchors)
#   - New survey .tif is in data/surveys/

set -euo pipefail

PROJECT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SLOPE_SCRIPTS=$PROJECT_DIR/slopes/little_prof
TOML=$PROJECT_DIR/slopes/little_prof/slope_config.toml
PIPELINE="python $PROJECT_DIR/src/avachain/forcing_pipeline.py --toml $TOML"
ANALYSIS="python $PROJECT_DIR/src/avachain/analysis_pipeline.py --toml $TOML"
NWP="python $PROJECT_DIR/src/avachain/nwp_ingest.py --toml $TOML"
SMET_APPEND="python $PROJECT_DIR/src/avachain/smet_append.py --toml $TOML"
CYCLE="python $PROJECT_DIR/src/avachain/snowpack_cycle.py --toml $TOML"
VENV=$PROJECT_DIR/.venv/bin/activate
# Every directory comes from the TOML (config.py --print-paths sets AVA_*),
# never from $PROJECT_DIR/outputs/...: a deployment relocates them.
source "$VENV"
# Assign first: a failing config.py inside eval "$(...)" would not trip set -e.
AVA_PATHS=$(python $PROJECT_DIR/src/avachain/config.py --toml $TOML --print-paths)
eval "$AVA_PATHS"
SLOPE_DIR=${SLOPE_DIR:-$AVA_SLOPE_DIR}
export SLOPE_DIR
LOG_DIR=$AVA_LOGS_DIR

SNAPSHOT_DATE=""
N_TRIGGERS=5
SIZE_FACTORS="0.7 0.85 1.0 1.15 1.3"
DEPTH_PCTS="10 50 90"
NO_NWP=0
NO_CLUSTER_UPDATE=0
NO_SCENARIOS=0
STABLE_TS=""

while [[ $# -gt 0 ]]; do
    case "$1" in
        --snapshot)          SNAPSHOT_DATE="$2"; shift 2 ;;
        --n-triggers)        N_TRIGGERS="$2"; shift 2 ;;
        --size-factors)      SIZE_FACTORS="$2"; shift 2 ;;
        --depth-pcts)        DEPTH_PCTS="$2"; shift 2 ;;
        --no-nwp)            NO_NWP=1; shift ;;
        --no-cluster-update) NO_CLUSTER_UPDATE=1; shift ;;
        --no-scenarios)      NO_SCENARIOS=1; shift ;;
        *)                   echo "Unknown arg: $1"; exit 1 ;;
    esac
done

mkdir -p "$LOG_DIR"
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
LOGFILE="$LOG_DIR/little_prof_${TIMESTAMP}.log"

# Survey markers ([surveys] markers = true, survey_markers.py): claim the
# oldest READY survey (READY → RUNNING) before the log opens, so a cron tick
# with nothing new leaves no log. The EXIT trap moves RUNNING to DONE or
# FAILED however the run ends. --snapshot is a manual rerun: no claim.
MARKERS="python $PROJECT_DIR/src/avachain/survey_markers.py --toml $TOML"
CLAIMED=""
CURRENT_STEP="setup"
if [[ $AVA_SURVEY_MARKERS -eq 1 && -z "$SNAPSHOT_DATE" ]]; then
    CLAIMED=$($MARKERS claim --pid $$ --log "$LOGFILE")
    [[ -z "$CLAIMED" ]] && exit 0
fi
_finish_marker() {
    local rc=$?
    [[ -z "$CLAIMED" ]] && return
    if [[ $rc -eq 0 ]]; then
        $MARKERS finish --survey-date "$CLAIMED" --status DONE --exit-code 0             --log "$LOGFILE" --output "$AVA_SCENARIOS_DIR"
    else
        $MARKERS finish --survey-date "$CLAIMED" --status FAILED --exit-code $rc             --step "$CURRENT_STEP" --log "$LOGFILE"
    fi
}
trap _finish_marker EXIT

exec > >(tee -a "$LOGFILE") 2>&1

cd "$PROJECT_DIR"

for f in "$AVA_ANALYSIS_DIR/cluster_map.npy" "$AVA_ANALYSIS_DIR/cluster_map.tif"; do
    if [[ ! -f "$f" ]]; then
        echo "ERROR: $f not found. Run the full pipeline first." >&2
        exit 1
    fi
done

# The survey this run is for: the latest one visible (respects $AVACHAIN_AS_OF).
SURVEY_DATE=$(python3 -c "
import sys; sys.path.insert(0, '$PROJECT_DIR/src/avachain')
from pathlib import Path
from config import ProjectConfig
from pipeline_io import discover_surveys
s = discover_surveys(ProjectConfig.from_toml(Path('$TOML')))
print(s[-1][0].isoformat() if s else '')
" 2>/dev/null | tail -1)
[[ -n "$CLAIMED" ]] && SURVEY_DATE=$CLAIMED
if [[ -z "$SURVEY_DATE" ]]; then
    echo "ERROR: no survey visible" >&2
    exit 1
fi

echo "============================================================"
echo "  Little Professor — Operational Pipeline Update (survey arrival)"
echo "  Started: $(date)"
echo "  Survey:  $SURVEY_DATE"
echo "  As-of:   ${AVACHAIN_AS_OF:-live}"
echo "  Log:     $LOGFILE"
echo "============================================================"
echo ""

SECONDS=0
SNAPSHOT_ARG=""
[[ -n "$SNAPSHOT_DATE" ]] && SNAPSHOT_ARG="--snapshot-date $SNAPSHOT_DATE"

echo ">>> Step 1: Resample"
CURRENT_STEP="Step 1: Resample"
step1_start=$SECONDS
$PIPELINE resample
step1_elapsed=$((SECONDS - step1_start))
echo "    Done: $((step1_elapsed / 60))m $((step1_elapsed % 60))s"
echo ""

echo ">>> Step 1b: Transport + avalanche detection on the new survey pair"
CURRENT_STEP="Step 1b: Transport + avalanche detection on the new survey pair"
step1b_start=$SECONDS
$PIPELINE transport
$PIPELINE avalanche
step1b_elapsed=$((SECONDS - step1b_start))
echo "    Done: $((step1b_elapsed / 60))m $((step1b_elapsed % 60))s"
echo ""

echo ">>> Step 2: Gap-fill"
CURRENT_STEP="Step 2: Gap-fill"
step2_start=$SECONDS
$PIPELINE gap_fill
step2_elapsed=$((SECONDS - step2_start))
echo "    Done: $((step2_elapsed / 60))m $((step2_elapsed % 60))s"
echo ""

echo ">>> Step 2b: Cluster update"
CURRENT_STEP="Step 2b: Cluster update"
step2b_start=$SECONDS
if [[ $NO_CLUSTER_UPDATE -eq 0 ]]; then
    $PIPELINE cluster_update
else
    echo "    Skipped (--no-cluster-update)"
fi
step2b_elapsed=$((SECONDS - step2b_start))
echo "    Done: $((step2b_elapsed / 60))m $((step2b_elapsed % 60))s"
echo ""

echo ">>> Step 2c: SMET generation + observations since the survey"
CURRENT_STEP="Step 2c: SMET generation + observations since the survey"
step2c_start=$SECONDS
$PIPELINE smet
# smet ends at the survey time; append station observations up to now.
$SMET_APPEND
step2c_elapsed=$((SECONDS - step2c_start))
echo "    Done: $((step2c_elapsed / 60))m $((step2c_elapsed % 60))s"
echo ""

echo ">>> Step 2d: NWP forecast extension"
CURRENT_STEP="Step 2d: NWP forecast extension"
step2d_start=$SECONDS
NWP_EDATE=""
if [[ $NO_NWP -eq 0 ]]; then
    $NWP --lead-hours 48 || echo "    WARNING: nwp_ingest failed — continuing without NWP extension"
    _ts_output=$(python3 -c "
import sys; sys.path.insert(0, '$PROJECT_DIR/src/avachain')
from nwp_ingest import get_stable_ts
from config import ProjectConfig
from pathlib import Path
import pandas as pd
cfg = ProjectConfig.from_toml(Path('$TOML'))
wrf = Path(cfg.wrf_smet_file) if cfg.wrf_smet_file else None
if wrf and wrf.exists():
    ts = get_stable_ts(wrf)
    if ts:
        print(ts.strftime('%Y-%m-%dT%H:%M'),
              (ts + pd.Timedelta(hours=48)).strftime('%Y-%m-%dT%H:%M'))
" 2>/dev/null)
    if [[ -n "$_ts_output" ]]; then
        STABLE_TS=$(echo "$_ts_output" | cut -d' ' -f1)
        NWP_EDATE=$(echo "$_ts_output" | cut -d' ' -f2)
        echo "    T_stable  = $STABLE_TS"
        echo "    NWP EDATE = $NWP_EDATE (T_stable + 48h)"
    else
        echo "    WRF not available; observed run only"
    fi
else
    echo "    Skipped (--no-nwp)"
fi
step2d_elapsed=$((SECONDS - step2d_start))
echo "    Done: $((step2d_elapsed / 60))m $((step2d_elapsed % 60))s"
echo ""

echo ">>> Step 3: SNOWPACK survey cycle (re-run from the previous survey)"
CURRENT_STEP="Step 3: SNOWPACK survey cycle (re-run from the previous survey)"
step3_start=$SECONDS
CYCLE_ARGS="survey --survey-date $SURVEY_DATE"
[[ -n "$STABLE_TS" ]] && CYCLE_ARGS="$CYCLE_ARGS --stable-ts $STABLE_TS --nwp-edate $NWP_EDATE"
$CYCLE $CYCLE_ARGS
step3_elapsed=$((SECONDS - step3_start))
echo "    Done: $((step3_elapsed / 60))m $((step3_elapsed % 60))s"
echo ""

echo ">>> Step 4: Analysis + scenario generation"
CURRENT_STEP="Step 4: Analysis + scenario generation"
step4_start=$SECONDS
$ANALYSIS analyze $SNAPSHOT_ARG
if [[ $NO_SCENARIOS -eq 0 ]]; then
    $ANALYSIS scenarios $SNAPSHOT_ARG \
        --n-triggers "$N_TRIGGERS" \
        --size-factors $SIZE_FACTORS \
        --depth-pcts $DEPTH_PCTS
else
    echo "    Scenarios skipped (--no-scenarios)"
fi
step4_elapsed=$((SECONDS - step4_start))
echo "    Done: $((step4_elapsed / 60))m $((step4_elapsed % 60))s"
echo ""

total_elapsed=$SECONDS
echo "============================================================"
echo "  Little Professor — Operational update complete"
echo "  Finished: $(date)"
echo "  Total:    $((total_elapsed / 3600))h $(((total_elapsed % 3600) / 60))m $((total_elapsed % 60))s"
echo ""
echo "  Step 1  (resample):        $((step1_elapsed / 60))m $((step1_elapsed % 60))s"
echo "  Step 1b (transport+avy):   $((step1b_elapsed / 60))m $((step1b_elapsed % 60))s"
echo "  Step 2  (gap_fill):        $((step2_elapsed / 60))m $((step2_elapsed % 60))s"
echo "  Step 2b (cluster_update):  $((step2b_elapsed / 60))m $((step2b_elapsed % 60))s"
echo "  Step 2c (smet):            $((step2c_elapsed / 60))m $((step2c_elapsed % 60))s"
echo "  Step 2d (nwp_ingest):      $((step2d_elapsed / 60))m $((step2d_elapsed % 60))s"
echo "  Step 3  (SNOWPACK cycle):  $((step3_elapsed / 60))m $((step3_elapsed % 60))s"
echo "  Step 4  (analysis):        $((step4_elapsed / 60))m $((step4_elapsed % 60))s"
echo ""
echo "  Scenarios: $AVA_SCENARIOS_DIR/"
echo "  Log:       $LOGFILE"
echo "============================================================"
